import{_ as a,o,c as i,a2 as l}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"AI 辅助编码工作流","description":"把 AI 编码工具当作需要校验的协作者，用在合适的任务上，并对它的产出保持审查。","frontmatter":{"title":"AI 辅助编码工作流","description":"把 AI 编码工具当作需要校验的协作者，用在合适的任务上，并对它的产出保持审查。"},"headers":[],"relativePath":"ai/ai-coding-workflow.md","filePath":"ai/ai-coding-workflow.md","lastUpdated":1786264437000}'),n={name:"ai/ai-coding-workflow.md"};function e(s,t,r,d,p,u){return o(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="ai-辅助编码工作流" tabindex="-1">AI 辅助编码工作流 <a class="header-anchor" href="#ai-辅助编码工作流" aria-label="Permalink to &quot;AI 辅助编码工作流&quot;">​</a></h1><p>AI 编码工具（从补全到对话式 Agent）已经改变写代码的方式，但把它当&quot;自动写正确代码的机器&quot;会让人失望，把它当&quot;需要校验的快速协作者&quot;才能用好。关键不在于工具多强，而在于你给它什么任务、怎么验证它的产出、以及哪些事坚决不交给它。</p><h2 id="它擅长什么-不擅长什么" tabindex="-1">它擅长什么，不擅长什么 <a class="header-anchor" href="#它擅长什么-不擅长什么" aria-label="Permalink to &quot;它擅长什么，不擅长什么&quot;">​</a></h2><p>先用对地方。AI 编码工具的能力分布很不均匀：</p><table tabindex="0"><thead><tr><th>擅长</th><th>不擅长</th></tr></thead><tbody><tr><td>写样板代码、CRUD、重复性脚手架</td><td>理解大型代码库的隐式约定和历史决策</td></tr><tr><td>解释报错、补全 API 用法</td><td>精确的边界条件和并发安全</td></tr><tr><td>单元测试草稿、类型定义</td><td>复杂业务规则的准确性</td></tr><tr><td>已有模式的迁移、重构</td><td>判断某段代码是否真的该存在</td></tr></tbody></table><p>擅长的部分放手给它，能省大量时间；不擅长的部分必须由人把关。最大的误区是&quot;它写得像对的，所以是对的&quot;——AI 生成的代码往往结构合理、命名规范，但会在边界情况、权限检查、错误处理这些细节上出错，而这些恰恰是 bug 的来源。</p><h2 id="上下文决定质量" tabindex="-1">上下文决定质量 <a class="header-anchor" href="#上下文决定质量" aria-label="Permalink to &quot;上下文决定质量&quot;">​</a></h2><p>AI 编码工具的输出质量，几乎完全取决于它看到的上下文。给它的信息越精准，结果越靠谱：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>差的提问：帮我写个登录功能。</span></span>
<span class="line"><span>好的提问：这是一个 Vue3 + TS 项目，用 Pinia 管理状态。</span></span>
<span class="line"><span>需要实现登录：调用 POST /api/auth/login，返回 { token, user }。</span></span>
<span class="line"><span>登录态存在 localStorage，401 时跳登录页。</span></span>
<span class="line"><span>已附上现有的 api.ts 和 auth store 结构。</span></span></code></pre></div><p>具体怎么做：</p><ul><li><strong>提供相关文件</strong>：把要修改的文件、它依赖的类型和接口、类似已有实现一起给工具，而不是让它猜项目结构。</li><li><strong>说清约束</strong>：用什么框架、遵循什么风格、不能碰哪些部分。不说约束，它会用最常见的默认实现，未必符合你的项目。</li><li><strong>给例子</strong>：让它&quot;照着现有的某个模式写&quot;，比描述模式更准确。</li></ul><h2 id="分小步-勤验证" tabindex="-1">分小步，勤验证 <a class="header-anchor" href="#分小步-勤验证" aria-label="Permalink to &quot;分小步，勤验证&quot;">​</a></h2><p>不要一次让 AI 生成一整个大功能。大块生成的代码很难验证——你能看出明显错误，但难以确认每一处细节都对。分小步推进：</p><ol><li>先让它搭结构或写接口定义，人审查通过。</li><li>再让它填实现，跑测试。</li><li>最后处理边界和错误路径。</li></ol><p>每一步都验证再往下走，比一次性生成再排错高效得多。AI 生成代码后，<strong>立即运行测试或手动验证</strong>，不要&quot;看起来对就提交&quot;。一个常见的失败模式是：AI 生成的代码能编译，逻辑却错了，人扫一眼觉得没问题就合进去，直到生产环境才暴露。</p><h2 id="代码审查不能省" tabindex="-1">代码审查不能省 <a class="header-anchor" href="#代码审查不能省" aria-label="Permalink to &quot;代码审查不能省&quot;">​</a></h2><p>AI 写的代码和真人写的代码一样需要审查，甚至更严格——因为它不会因为&quot;不确定&quot;而停下来问你：</p><ul><li><strong>边界条件</strong>：空值、并发、超时、重复请求，这些它容易忽略。</li><li><strong>安全</strong>：是否信任了外部输入、是否有注入风险、权限检查是否到位。</li><li><strong>是否存在</strong>：有时候它会&quot;好心&quot;加一个根本不需要的功能或抽象。</li><li><strong>是否符合项目约定</strong>：命名、错误处理风格、目录结构。</li></ul><p>审查 AI 代码的一个原则：<strong>如果你无法解释这段代码为什么对，就不要保留它</strong>。看不懂就要求工具解释，或者自己重写到能理解。看不懂的代码是未来的债。</p><h2 id="哪些事要特别谨慎" tabindex="-1">哪些事要特别谨慎 <a class="header-anchor" href="#哪些事要特别谨慎" aria-label="Permalink to &quot;哪些事要特别谨慎&quot;">​</a></h2><p>有些任务，AI 工具能用，但风险显著更高，需要额外的把关：</p><ul><li><strong>涉及鉴权、支付、数据迁移</strong>的代码：一个细节错就是事故，必须人工逐行审。</li><li><strong>删除或大规模重写</strong>：AI 不理解某段&quot;奇怪&quot;代码可能是为了修某个历史 bug，贸然删掉会回归。</li><li><strong>性能敏感路径</strong>：AI 倾向写&quot;清晰&quot;的代码，不一定是&quot;快&quot;的代码。</li><li><strong>依赖隐式业务规则</strong>的部分：这些规则不在代码里，在人的脑子里，AI 看不到。</li></ul><p>对这类任务，用 AI 起草或探索方案，但最终决策和验证由人完成。</p><h2 id="把交互沉淀成项目约定" tabindex="-1">把交互沉淀成项目约定 <a class="header-anchor" href="#把交互沉淀成项目约定" aria-label="Permalink to &quot;把交互沉淀成项目约定&quot;">​</a></h2><p>用 AI 编码多了，会发现某些反复出现的问题——比如它总用错状态管理方式、总把 API 调用写在组件里。这些可以通过项目级的约定文件解决：把架构规则、风格约束、禁区写进文档，让工具（或新成员）每次都能读到。约束越显式，AI 的产出越贴合项目，反复纠正的次数越少。</p><h2 id="务实的工作清单" tabindex="-1">务实的工作清单 <a class="header-anchor" href="#务实的工作清单" aria-label="Permalink to &quot;务实的工作清单&quot;">​</a></h2><ul><li>这个任务是否适合交给 AI（样板/测试/解释 vs. 复杂业务规则）？</li><li>是否提供了足够的相关上下文和约束？</li><li>是否分小步推进，每步都验证而不是一次性生成？</li><li>生成的代码我能否逐行解释？边界、安全、错误处理是否到位？</li><li>高风险改动（鉴权/支付/迁移）是否有额外的人工审查？</li></ul><p>AI 编码工具真正放大的，是有判断力的工程师的效率——他们知道该让工具做什么、怎么验证、哪里不能信。对于缺乏判断的场景，它反而可能加速制造难以察觉的问题。把它当协作者，保持你作为最终负责人的审查权，才能拿到它带来的效率红利。</p>`,28)])])}const g=a(n,[["render",e]]);export{c as __pageData,g as default};
